// LDT entry structure for func=1 or 0x11 (WRITE)
struct user_desc {
    unsigned int entry_number;
    unsigned int base_addr;
    unsigned int limit;
    unsigned int flags; // Type, S, DPL, P, AVL, L, D/B, G
};

struct user_desc new_seg = {
    .entry_number = 5,
    .base_addr = 0x40000000,
    .limit = 0xFFF,
    .flags = 0xC0F2 // 32-bit, Granularity 4K, Data Writeable
};

// func=1: Modify LDT entry 5
long write_res = modify_ldt(1, &new_seg, sizeof(new_seg));

// func=0: Read LDT entries into buffer (e.g., 2 LDT entries)
#define NUM_ENTRIES 2
struct user_desc ldt_buf[NUM_ENTRIES];
long read_res = modify_ldt(0, ldt_buf, sizeof(ldt_buf));
